Here's a complete example of a C# MCP server that wraps a REST API using stdio transport.

## Program.cs

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: log to stderr only — stdout is reserved for JSON-RPC protocol
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

builder.Services.AddHttpClient("api", client =>
{
    client.BaseAddress = new Uri("https://api.example.com");
});

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

await builder.Build().RunAsync();
```

## ApiTools.cs

```csharp
using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public class ApiTools(IHttpClientFactory httpFactory, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Get a user profile by ID.")]
    public async Task<string> GetUser(
        [Description("The unique user ID")] string userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var client = httpFactory.CreateClient("api");
        return await client.GetStringAsync($"/users/{userId}", cancellationToken);
    }

    [McpServerTool, Description("Search users by name. Returns matching results.")]
    public async Task<string> SearchUsers(
        [Description("Search query string")] string query,
        [Description("Max results to return (1-50)")] int limit = 10,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var response = await client.GetStringAsync(
            $"/users?q={Uri.EscapeDataString(query)}&limit={limit}",
            cancellationToken);
        return response;
    }

    [McpServerTool(ReadOnly = false, Destructive = false),
     Description("Create a new user account.")]
    public async Task<string> CreateUser(
        [Description("Display name for the user")] string name,
        [Description("Email address")] string email,
        CancellationToken cancellationToken = default)
    {
        var client = httpFactory.CreateClient("api");
        var response = await client.PostAsJsonAsync(
            "/users", new { name, email }, cancellationToken);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

## How DI works for MCP tools

The SDK supports **two injection styles**:

**1. Constructor injection (non-static class, shown above)**
The class is instantiated by the DI container per invocation. Services like `IHttpClientFactory` and `ILogger<T>` are resolved via the constructor. These **never** appear in the tool's JSON schema — only `[Description]`-annotated parameters do.

**2. Method parameter injection (static class)**
```csharp
[McpServerToolType]
public static class StaticTools
{
    [McpServerTool, Description("Ping the API.")]
    public static async Task<string> Ping(
        HttpClient httpClient,           // ← injected by DI, hidden from schema
        CancellationToken cancellationToken = default)
    {
        return await httpClient.GetStringAsync("/health", cancellationToken);
    }
}
```

**Auto-injected types** (never in schema): `CancellationToken`, `IMcpServer`, `IProgress<ProgressNotificationValue>`, and any DI-registered service.

### Key rules
| Rule | Why |
|------|-----|
| `[Description]` on every tool + param | LLMs use these to decide when/how to call tools |
| Logging → stderr only | stdout is the JSON-RPC transport channel |
| `WithToolsFromAssembly()` | Auto-discovers all `[McpServerToolType]` classes |
| `CancellationToken` on async methods | Enables cooperative cancellation |

Scaffold this with `dotnet new mcpserver -n YourProjectName`, or manually create a console project and `dotnet add package ModelContextProtocol`.
